local OverseaManagerPersonnelCatCell = Class('OverseaManagerPersonnelCatCell')
local MaidCoffeeMgr = import('Game.MaidCoffee.MaidCoffeeMgr')
local MaidCoffeeConstants = import("Game.MaidCoffee.MaidCoffeeConstants")
local MaidCoffeeUtils     = import("Game.MaidCoffee.MaidCoffeeUtils")
local KTool = CS.Engine.Lib.KTool
local UIModule = CS.Engine.UI.UIModule
local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
local cs_coroutine = require 'XLua.cs_coroutine'
function OverseaManagerPersonnelCatCell:__init()
    self.ownerId = nil
end

function OverseaManagerPersonnelCatCell:__delete()
    self.ownerId = nil
end

function OverseaManagerPersonnelCatCell:Awake()
    self:AddUIClick()
    self:PlayShowEffect(false)
end

function OverseaManagerPersonnelCatCell:AddUIClick()
    SetButtonAction(self.BtnNode,Bind(self,self.OnBtnNodeClick))
    SetButtonAction(self.BtnSet,Bind(self,self.OnBtnSetClick))
end


function OverseaManagerPersonnelCatCell:SetShowCatCallBack(callBack)
    self.callBack = callBack
end

function OverseaManagerPersonnelCatCell:RefreshCatShow(index)
    local isLocked, desc = MaidCoffeeMgr:GetInstance():GetIsLocked(MaidCoffeeConstants.SelectType.Cat,index)
    self.isLocked = isLocked
    self.lockDesc = desc


    KTool.SetActive(self.Lock.gameObject,isLocked)
    if isLocked then
        KTool.SetActive(self.CanAdd.gameObject,not isLocked)
        KTool.SetActive(self.Content.gameObject,not isLocked)
        CfUtils.FillText(self.LockDes,self.lockDesc)
        return
    end

    local redGo = GameUtils.GetRedPointGo(self.CanAdd.gameObject)
    local isPutCat = component:IsHaveCatToPutOn()
    if not isNull(redGo) then
        KTool.SetActive(redGo,isPutCat)
    end

    local ownerId = component:GetStaffInfoByType(MaidCoffeeConstants.SelectType.Cat ,index)
    self.isCanAdd =  tonumber(ownerId) == 0
    self.ownerId = ownerId
    KTool.SetActive(self.CanAdd.gameObject,self.isCanAdd)
    KTool.SetActive(self.Content.gameObject,not self.isCanAdd)
    ---不能添加  说明是有owner了
    if not self.isCanAdd then
        ---@type CatEggComponent
        local eggComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatEggComponent)
        local dojo = eggComponent:GetCat(ownerId)
        if not isNull(dojo) then
            local CatBallUtils =  import("Game.CatBall.CatBallUtils")
            ---@type CatBallVo
            local catBallVo = CatBallUtils.GetCatBallVo(dojo.catId)
            if not isNull(catBallVo) then
                CfUtils.FillText(self.Name,catBallVo.name)
                CfUtils.FillImage(self.ImgCatBallIcon,catBallVo.picture)
                local _, _, skillVo = CatBallUtils.GetCatBallSkillDesc(dojo.catId, dojo.star, catBallVo.types, false)
                CfUtils.FillImage(self.ImgSkillIcon,skillVo.icon)
            end
        end
        self:RefreshIsShowCat(ownerId)
    end
end

function OverseaManagerPersonnelCatCell:OnBtnNodeClick()
    if self.isLocked then
        GameUtils.Toast(self.lockDesc)
        return
    end

    CfUtils.DialogOpen(
            Constants.UITypeIds.CatBallChooseCardsDialog,
            {teamType = Constants.EditTeamCatType.Operates, catBallType = Constants.CatBallType.Operates},
            nil, true)
end

function OverseaManagerPersonnelCatCell:OnBtnSetClick()
    if not self.isCanAdd then
        local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
        local showCatId = component:GetShowCatId()
        if showCatId == self.ownerId then
            GameUtils.Toast(localize("当前猫球已展示在吧台"))
            return
        end

        GameUtils.Request(Interfaces.MaidCoffeeSetShowCat,{playerCatId = self.ownerId},function(request,response)
            if checkNumber(response.errCode) == 0 then
                local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
                component:UpdateShowCatId(self.ownerId)
                Events.Broadcast(MaidCoffeeConstants.EventNames.MaidCoffeeChangeShowCat)
                if not isNull(self.callBack) then
                    self.callBack(self.ownerId)
                end
            end
        end)
    end
end

function OverseaManagerPersonnelCatCell:PlayShowEffect(status)
    KTool.SetActive(self.UIFX_ShowGlow.gameObject,status)
end

function OverseaManagerPersonnelCatCell:RefreshIsShowCat(id)
    local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local showCatId = component:GetShowCatId()
    local status = showCatId == id and 2 or 1
    CfUtils.SetUISwitchImage(self.ImgSymbol,status)
end


function OverseaManagerPersonnelCatCell:Start()
end

function OverseaManagerPersonnelCatCell:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return OverseaManagerPersonnelCatCell